package com.sisge.ms.entity;
import jakarta.persistence.*; import java.time.*; import java.math.BigDecimal; import com.sisge.ms.entity.Importacion; import com.sisge.ms.entity.Organizacion;
@Entity @Table(name="reemplazantes_historico") public class ReemplazanteHistorico { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="organizacion_id",nullable=false) private Organizacion organizacion; @ManyToOne @JoinColumn(name="importacion_id",nullable=false) private Importacion importacion; private String archivoOrigen; private int filaOrigen; private String reemplazante; private String cuil; private String categoriaReemplazante; private LocalDate periodoDesde,periodoHasta,licenciaDesde,licenciaHasta; private BigDecimal aPagar,aDeuda; private String titular,categoriaTitular,instrumentoLegal,tipoLicenciaExcel,agrupamiento,funcionTitular,tipoLicencia,observaciones,lugarTrabajo; private Integer cantidadDias; private Instant fechaCierre=Instant.now(); public Long getId(){return id;} public String getCuil(){return cuil;} public String getReemplazante(){return reemplazante;} public Importacion getImportacion(){return importacion;} public Organizacion getOrganizacion(){return organizacion;} public String getTitular(){return titular;} public String getLugarTrabajo(){return lugarTrabajo;} public Instant getFechaCierre(){return fechaCierre;} public String getArchivoOrigen(){return archivoOrigen;} public int getFilaOrigen(){return filaOrigen;} public String getCategoriaReemplazante(){return categoriaReemplazante;} public String getInstrumentoLegal(){return instrumentoLegal;} public LocalDate getPeriodoDesde(){return periodoDesde;} public LocalDate getPeriodoHasta(){return periodoHasta;} public BigDecimal getAPagar(){return aPagar;} public BigDecimal getADeuda(){return aDeuda;} public String getCategoriaTitular(){return categoriaTitular;} public LocalDate getLicenciaDesde(){return licenciaDesde;} public LocalDate getLicenciaHasta(){return licenciaHasta;} public Integer getCantidadDias(){return cantidadDias;} public String getTipoLicenciaExcel(){return tipoLicenciaExcel;} public String getAgrupamiento(){return agrupamiento;} public String getFuncionTitular(){return funcionTitular;} public String getTipoLicencia(){return tipoLicencia;} public String getObservaciones(){return observaciones;} public static ReemplazanteHistorico from(ImportacionReemplazante r){ var h=new ReemplazanteHistorico(); h.importacion=r.getImportacion();h.organizacion=r.getImportacion().getOrganizacion();h.archivoOrigen=r.getImportacion().getArchivoOrigen();h.filaOrigen=r.getFilaOrigen();h.reemplazante=r.getReemplazante();h.cuil=r.getCuil();h.categoriaReemplazante=r.getCategoriaReemplazante();h.instrumentoLegal=r.getInstrumentoLegal();h.periodoDesde=r.getPeriodoDesde();h.periodoHasta=r.getPeriodoHasta();h.aPagar=r.getAPagar();h.aDeuda=r.getADeuda();h.titular=r.getTitular();h.categoriaTitular=r.getCategoriaTitular();h.licenciaDesde=r.getLicenciaDesde();h.licenciaHasta=r.getLicenciaHasta();h.cantidadDias=r.getCantidadDias();h.tipoLicenciaExcel=r.getTipoLicenciaExcel();h.agrupamiento=r.getAgrupamiento();h.funcionTitular=r.getFuncionTitular();h.tipoLicencia=r.getTipoLicencia();h.observaciones=r.getObservaciones();h.lugarTrabajo=r.getLugarTrabajo();return h;} }
